{"file_path":"src/dot-segments.js","content":"/**
 * Removes dot segments from a URI path per RFC 3986 section 5.2.4.
 */

function removeLastSegment(output) {
  const idx = output.lastIndexOf('/')
  return idx === -1 ? '' : output.slice(0, idx)
}

export function removeDotSegments(path) {
  let input = path
  let output = ''
  while (input.length > 0) {
    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = '/' + input.slice(3)
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = '/' + input.slice(4)
      output = removeLastSegment(output)
    } else if (input === '/..') {
      input = '/'
      output = removeLastSegment(output)
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      const idx = input.indexOf('/', 1)
      let segment
      if (idx === -1) {
        segment = input
        input = ''
      } else {
        segment = input.slice(0, idx)
        input = input.slice(idx)
      }
      output += segment
    }
  }
  return output
}
"}

