{"file_path":"src/normalize.js","content":"/**
 * Normalizes a parsed URI reference: percent-encoding, scheme and host
 * case, default ports, and dot segments, in the order RFC 3986 and the
 * task specification give.
 */

import { removeDotSegments } from './dot-segments.js'

const DEFAULT_PORTS = { http: '80', https: '443', ws: '80', wss: '443', ftp: '21' }

export class PercentEncodingError extends Error {
  constructor(component) {
    super(`the ${component} has a truncated percent-encoding`)
    this.component = component
  }
}

function isUnreserved(ch) {
  return /^[A-Za-z0-9\-._~]$/.test(ch)
}

function normalizePercent(text, component) {
  let out = ''
  for (let i = 0; i < text.length; i++) {
    const ch = text[i]
    if (ch !== '%') {
      out += ch
      continue
    }
    const hex = text.slice(i + 1, i + 3)
    if (!/^[0-9a-fA-F]{2}$/.test(hex)) {
      throw new PercentEncodingError(component)
    }
    const upper = hex.toUpperCase()
    const code = parseInt(upper, 16)
    const decoded = String.fromCharCode(code)
    out += isUnreserved(decoded) ? decoded : '%' + upper
    i += 2
  }
  return out
}

function asciiLowercase(text) {
  return text.replace(/[A-Z]/g, (c) => c.toLowerCase())
}

export function normalizeReference(ref) {
  const scheme = ref.scheme !== null ? asciiLowercase(ref.scheme) : null

  const path = normalizePercent(ref.path, 'path')

  let authority = null
  if (ref.authority !== null) {
    const userinfo = ref.authority.userinfo !== null
      ? normalizePercent(ref.authority.userinfo, 'userinfo')
      : null
    const host = asciiLowercase(normalizePercent(ref.authority.host, 'host'))
    let port = ref.authority.port
    if (port === '' || (scheme !== null && port === DEFAULT_PORTS[scheme])) {
      port = null
    }
    authority = { userinfo, host, port }
  }

  const query = ref.query !== null ? normalizePercent(ref.query, 'query') : null
  const fragment = ref.fragment !== null ? normalizePercent(ref.fragment, 'fragment') : null

  let finalPath = removeDotSegments(path)
  if (authority !== null && finalPath === '') finalPath = '/'

  return { scheme, authority, path: finalPath, query, fragment }
}
"}

