import { parseReference, serializeReference } from './parse.js'
import { normalizeReference, PercentEncodingError } from './normalize.js'
import { resolveReference } from './resolve.js'

class UsageError extends Error {}
class LineError extends Error {}

function splitRecords(text) {
  if (text === '') return []
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  return lines
}

function processNormalize(line) {
  const ref = parseReference(line)
  const normalized = normalizeReference(ref)
  return serializeReference(normalized)
}

function processResolve(line) {
  const spaceIdx = line.indexOf(' ')
  if (spaceIdx === -1) {
    throw new LineError('expected a base and a reference')
  }
  const baseText = line.slice(0, spaceIdx)
  const refText = line.slice(spaceIdx + 1)

  const base = parseReference(baseText)
  if (base.scheme === null) {
    throw new LineError('the base has no scheme')
  }
  const ref = parseReference(refText)

  const target = resolveReference(base, ref)
  const normalized = normalizeReference(target)
  return serializeReference(normalized)
}

function readStdin() {
  return new Promise((resolve, reject) => {
    const chunks = []
    process.stdin.on('data', (chunk) => chunks.push(chunk))
    process.stdin.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')))
    process.stdin.on('error', reject)
  })
}

async function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
    throw new UsageError()
  }
  const mode = args[0]

  const text = await readStdin()
  const records = splitRecords(text)

  const results = []
  for (let i = 0; i < records.length; i++) {
    const n = i + 1
    const line = records[i]
    try {
      results.push(mode === 'normalize' ? processNormalize(line) : processResolve(line))
    } catch (err) {
      if (err instanceof PercentEncodingError) {
